<?php
if ($page === 'visit') {
                $clinicId = currentClinicId();
                $visitId = (int)($_GET['id'] ?? 0);
                $stmt = $pdo->prepare('SELECT v.*, p.patient_number, p.full_name, p.date_of_birth, p.gender, p.phone, p.email, p.address, p.insurance_provider, p.insurance_number FROM visits v JOIN patients p ON p.id=v.patient_id AND p.clinic_id=v.clinic_id WHERE v.id=? AND v.clinic_id=?');
                $stmt->execute([$visitId, $clinicId]);
                $visit = $stmt->fetch();
                if (!$visit) {
                    echo '<div class="notice error">Visit not found. <a href="?page=dashboard">Return to dashboard</a></div>';
                } else {
                    $stmt = $pdo->prepare('SELECT * FROM triage WHERE visit_id=?'); $stmt->execute([$visitId]); $triage = $stmt->fetch() ?: [];
                    $stmt = $pdo->prepare('SELECT * FROM consultations WHERE visit_id=?'); $stmt->execute([$visitId]); $consult = $stmt->fetch() ?: [];
                    $stmt = $pdo->prepare('SELECT lo.*, lr.id result_id, lr.result_text, lr.report_file FROM lab_orders lo LEFT JOIN lab_results lr ON lr.lab_order_id=lo.id WHERE lo.visit_id=? ORDER BY lo.id'); $stmt->execute([$visitId]); $labs = $stmt->fetchAll();
                    $stmt = $pdo->prepare('SELECT p.*, u.full_name prescriber, prep.full_name preparer, disp.full_name dispenser FROM prescriptions p LEFT JOIN users u ON u.id=p.prescribed_by LEFT JOIN users prep ON prep.id=p.prepared_by LEFT JOIN users disp ON disp.id=p.dispensed_by WHERE p.visit_id=? ORDER BY p.id DESC'); $stmt->execute([$visitId]); $prescriptions = $stmt->fetchAll();
                    $stmt = $pdo->prepare('SELECT pi.*, m.name, m.strength, m.unit_price FROM prescription_items pi JOIN prescriptions p ON p.id=pi.prescription_id JOIN medicines m ON m.id=pi.medicine_id AND m.clinic_id=? WHERE p.visit_id=? ORDER BY pi.id'); $stmt->execute([$clinicId, $visitId]); $prescriptionItems = $stmt->fetchAll();
                    $stmt = $pdo->prepare('SELECT * FROM follow_ups WHERE visit_id=? ORDER BY scheduled_date'); $stmt->execute([$visitId]); $followups = $stmt->fetchAll();
                    $stmt = $pdo->prepare('SELECT i.*, COALESCE((SELECT SUM(pi.quantity*m.unit_price) FROM prescriptions p JOIN prescription_items pi ON pi.prescription_id=p.id JOIN medicines m ON m.id=pi.medicine_id AND m.clinic_id=? WHERE p.visit_id=i.visit_id),0) medicine_total, COALESCE((SELECT SUM(amount) FROM payments WHERE invoice_id=i.id),0) paid FROM invoices i WHERE i.visit_id=?'); $stmt->execute([$clinicId, $visitId]); $invoice = $stmt->fetch();
                    $invoiceTotal = $invoice ? (float)$invoice['consultation_fee'] + (float)$invoice['other_charges'] + (float)$invoice['medicine_total'] : 0;
                    $workflow = visitWorkflow($pdo, $visitId);
                    ?>
                    <div class="page-head"><div><h1><?= h($visit['full_name']) ?></h1><p class="subheading"><?= h($visit['patient_number']) ?> · Queue #<?= (int)$visit['queue_number'] ?> · <?= h($visit['visit_date']) ?></p></div><div><?= statusBadge($visit['status']) ?></div></div>
                    <?php if ($workflow['completed']): ?><div class="notice success">This visit is closed. Its clinical and billing records are read-only.</div><?php endif; ?>
                    <section class="card"><div class="workflow"><?php foreach ($workflow['steps'] as $i=>[$label, $done]): if ($i > $workflow['current_step']) break; ?><div class="workflow-step<?= $done ? ' done' : '' ?><?= $i === $workflow['current_step'] ? ' current' : ' locked' ?>"><div class="workflow-dot"><?= $done ? '✓' : ($i+1) ?></div><?= h($label) ?></div><?php endforeach; ?></div>
                        <div class="detail-list"><div><span>Patient ID</span><strong><?= h($visit['patient_number']) ?></strong></div><div><span>Gender / age</span><strong><?= h($visit['gender']) ?> · <?= h(ageAt($visit['date_of_birth'])) ?></strong></div><div><span>Contact</span><strong><?= h($visit['phone'] ?: '—') ?></strong></div><div><span>Insurance</span><strong><?= h($visit['insurance_provider'] ?: '—') ?><?= $visit['insurance_number'] ? ' · ' . h($visit['insurance_number']) : '' ?></strong></div><div><span>Visit reason</span><strong><?= h($visit['reason_for_visit'] ?: '—') ?></strong></div><div><span>Address / email</span><strong><?= h($visit['address'] ?: $visit['email'] ?: '—') ?></strong></div></div>
                    </section>
                    <div class="grid-2" style="margin-top:18px">
                        <section class="card"><h2>Nurse assessment & vital signs</h2>
                            <?php if ($workflow['can_triage']): ?>
                                <p class="hint">Complete all vital signs and initial complaints before the doctor can begin.</p><?php formStart('triage', 'triage:' . $visitId); ?><input type="hidden" name="visit_id" value="<?= $visitId ?>"><div class="form-grid">
                                    <?php field('Weight (kg)', 'weight_kg', $triage['weight_kg'] ?? '', 'number', true); field('Height (cm)', 'height_cm', $triage['height_cm'] ?? '', 'number', true); field('Blood pressure', 'blood_pressure', $triage['blood_pressure'] ?? '', 'text', true, '120/80'); field('Temperature (°C)', 'temperature_c', $triage['temperature_c'] ?? '', 'number', true); field('Pulse rate (bpm)', 'pulse_bpm', $triage['pulse_bpm'] ?? '', 'number', true); field('Oxygen level (%)', 'oxygen_percent', $triage['oxygen_percent'] ?? '', 'number', true); textareaField('Initial complaints', 'complaints', $triage['complaints'] ?? '', true, true); ?>
                                </div><div class="actions"><button class="btn btn-primary">Save triage & continue</button></div></form>
                            <?php elseif ($workflow['triage_done']): ?>
                                <div class="detail-list"><div><span>Weight</span><strong><?= h($triage['weight_kg'] ?? '—') ?> kg</strong></div><div><span>Height</span><strong><?= h($triage['height_cm'] ?? '—') ?> cm</strong></div><div><span>Blood pressure</span><strong><?= h($triage['blood_pressure'] ?? '—') ?></strong></div><div><span>Temperature</span><strong><?= h($triage['temperature_c'] ?? '—') ?> °C</strong></div><div><span>Pulse</span><strong><?= h($triage['pulse_bpm'] ?? '—') ?> bpm</strong></div><div><span>Oxygen</span><strong><?= h($triage['oxygen_percent'] ?? '—') ?>%</strong></div><div><span>Initial complaints</span><strong><?= h($triage['complaints'] ?? '—') ?></strong></div></div><div class="notice info" style="margin:15px 0 0">Triage is saved. Vital signs are locked after the doctor starts.</div>
                            <?php else: ?>
                                <div class="notice info">Complete patient check-in before entering vital signs.</div>
                            <?php endif; ?>
                        </section>
                        <?php if ($workflow['triage_done']): ?><section class="card"><h2>Doctor consultation</h2>
                            <?php if (!$workflow['triage_done']): ?>
                                <div class="notice info">Locked until the nurse completes triage.</div>
                            <?php elseif (!$workflow['labs_done']): ?>
                                <div class="notice info">The doctor review is paused until every requested laboratory test has a result.</div>
                            <?php elseif ($workflow['consultation_done']): ?>
                                <div class="detail-list"><div><span>Diagnosis</span><strong><?= h($consult['diagnosis']) ?></strong></div><div><span>Treatment plan</span><strong><?= h($consult['treatment_plan']) ?></strong></div><div><span>Final assessment</span><strong><?= h($consult['final_assessment']) ?></strong></div></div><div class="notice success" style="margin:15px 0 0"><?= $workflow['lab_count'] > 0 ? 'Results reviewed and consultation completed.' : 'Consultation completed.' ?></div>
                            <?php elseif (!$workflow['can_consult']): ?>
                                <div class="notice info">The doctor consultation unlocks after triage and any pending tests are complete.</div>
                            <?php else: ?>
                                <?php if (in_array($visit['status'], ['Ready for Doctor','Results Available'], true)): ?><?php formStart('start_consultation'); ?><input type="hidden" name="visit_id" value="<?= $visitId ?>"><button class="btn btn-primary btn-small" style="margin-bottom:12px"><?= $workflow['lab_count'] > 0 ? 'Start results review' : 'Start doctor consultation' ?></button></form><?php endif; ?>
                                <?php if ($visit['status'] === 'In Consultation'): ?><?php formStart('consult', 'consult:' . $visitId); ?><input type="hidden" name="visit_id" value="<?= $visitId ?>"><div class="form-grid">
                                    <?php textareaField('Chief complaint', 'chief_complaint', $consult['chief_complaint'] ?? '', false, true); textareaField('Medical history', 'medical_history', $consult['medical_history'] ?? ''); textareaField('Symptoms', 'symptoms', $consult['symptoms'] ?? ''); textareaField('Physical examination', 'examination', $consult['examination'] ?? ''); textareaField('Diagnosis', 'diagnosis', $consult['diagnosis'] ?? '', false, true); textareaField('Treatment plan', 'treatment_plan', $consult['treatment_plan'] ?? ''); textareaField('Final assessment / outcome', 'final_assessment', $consult['final_assessment'] ?? ''); field('Order a lab / imaging test (optional)', 'test_name'); textareaField('Test instructions', 'lab_instructions', '', true); ?>
                                </div><p class="hint">Chief complaint and diagnosis are needed to save. Complete the treatment plan and final assessment to finish this step; if you order tests, complete them before the final doctor review.</p><div class="actions"><button class="btn btn-primary"><?= $workflow['lab_count'] > 0 ? 'Save doctor review' : 'Save consultation & continue' ?></button></div></form><?php endif; ?>
                            <?php endif; ?>
                        </section><?php endif; ?>
                    </div>
                    <?php if ($workflow['lab_count'] > 0 || $workflow['completed']): ?><section class="card"><h2>Laboratory & radiology orders</h2><div class="table-wrap"><table><thead><tr><th>Investigation</th><th>Ordered</th><th>Status / result</th><th>Action</th></tr></thead><tbody>
                    <?php if (!$labs): ?><tr><td colspan="4" class="empty">No tests ordered for this visit.</td></tr><?php endif; ?>
                    <?php foreach ($labs as $lab): ?><tr><td><strong><?= h($lab['test_name']) ?></strong><div class="person-meta"><?= h($lab['instructions'] ?: '') ?></div></td><td><?= h($lab['ordered_at']) ?></td><td><?= statusBadge($lab['status']) ?><?php if ($lab['result_text']): ?><div class="person-meta" style="white-space:pre-wrap;margin-top:7px"><?= h($lab['result_text']) ?></div><?php endif; ?><?php if ($lab['report_file']): ?><a class="person-meta" href="?page=report&id=<?= (int)$lab['result_id'] ?>">View uploaded report</a><?php endif; ?></td><td>
                    <?php if ($workflow['can_process_labs'] && $lab['status'] !== 'Results Available'): ?><?php if ($lab['status'] === 'Ordered'): ?><?php formStart('lab_start'); ?><input type="hidden" name="visit_id" value="<?= $visitId ?>"><input type="hidden" name="lab_order_id" value="<?= (int)$lab['id'] ?>"><button class="btn btn-light btn-small">Start test</button></form><?php endif; ?>
                        <details style="margin-top:7px"><summary style="cursor:pointer;color:#246bce;font-size:11px">Enter result</summary><?php formStart('lab_result', 'lab_result:' . (int)$lab['id']); ?><input type="hidden" name="visit_id" value="<?= $visitId ?>"><input type="hidden" name="lab_order_id" value="<?= (int)$lab['id'] ?>"><textarea name="result_text" required placeholder="Test findings / result"></textarea><input type="file" name="report" accept=".pdf,.jpg,.jpeg,.png,application/pdf,image/jpeg,image/png" style="margin-top:7px"><span class="hint">Optional PDF, JPG, PNG · max 5 MB</span><button class="btn btn-primary btn-small" style="margin-top:8px">Save result</button></form></details>
                    <?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php endif; ?>
                    <?php if ($workflow['consultation_done'] || $workflow['prescription_count'] > 0 || $workflow['completed']): ?>
                        <section class="card"><h2>Prescription</h2>
                            <div class="table-wrap"><table><thead><tr><th>Medicine</th><th>Directions</th><th>Qty</th><th>Dispensed</th></tr></thead><tbody>
                            <?php if (!$prescriptionItems): ?><tr><td colspan="4" class="empty">No prescription items.</td></tr><?php endif; ?>
                            <?php foreach ($prescriptionItems as $item): ?><tr><td><?= h($item['name']) ?><div class="person-meta"><?= h($item['strength'] ?: '') ?></div></td><td><?= h($item['dosage']) ?> · <?= h($item['duration']) ?><div class="person-meta"><?= h($item['instructions'] ?: '') ?></div></td><td><?= (int)$item['quantity'] ?></td><td><?= (int)$item['dispensed_quantity'] ?></td></tr><?php endforeach; ?>
                            </tbody></table></div>
                            <?php $stmt = $pdo->prepare('SELECT id, name, strength, stock_quantity FROM medicines WHERE clinic_id=? AND active=1 ORDER BY name'); $stmt->execute([$clinicId]); $medicines = $stmt->fetchAll(); if ($workflow['can_prescribe'] && $medicines): ?>
                            <hr class="line"><h3 style="font-size:13px">Add prescription item</h3><?php formStart('prescribe', 'prescribe:' . $visitId); ?><input type="hidden" name="visit_id" value="<?= $visitId ?>"><div class="form-grid">
                                <div class="field full"><label>Medicine</label><select name="medicine_id" required><option value="">Select medicine</option><?php foreach ($medicines as $med): ?><option value="<?= (int)$med['id'] ?>"><?= h($med['name']) ?> <?= h($med['strength']) ?> · stock <?= (int)$med['stock_quantity'] ?></option><?php endforeach; ?></select></div>
                                <?php field('Dosage', 'dosage', '', 'text', true, 'e.g. 1 tablet twice daily'); field('Duration', 'duration', '', 'text', true, 'e.g. 5 days'); field('Quantity', 'quantity', '', 'number', true); field('Usage instructions', 'instructions'); ?>
                            </div><div class="actions"><button class="btn btn-primary">Add to prescription</button></div></form><?php elseif (!$workflow['can_prescribe'] && !$workflow['completed']): ?><div class="notice info">Add a prescription after the doctor has completed the treatment plan and any result review.</div><?php elseif (!$medicines): ?><div class="empty">Add medicines in the Pharmacy section to prescribe.</div><?php endif; ?>
                        </section>
                    <?php endif; ?>
                    <?php if ($workflow['prescription_count'] > 0 || $workflow['completed']): ?><section class="card"><h2>Pharmacy handoff & dispensing</h2><p class="hint">Pharmacy prepares the prescribed items and prints a prescription slip. The patient takes it to the cashier, pays, receives a receipt, then returns here. Verify that receipt before dispensing.</p>
                        <?php foreach ($prescriptions as $rx): ?><div class="prescription-handoff"><div class="page-head"><div><strong>Prescription #<?= (int)$rx['id'] ?></strong><span class="hint">Prescribed by <?= h($rx['prescriber'] ?: 'Clinic staff') ?> · <?= h($rx['created_at']) ?></span></div><?= statusBadge($rx['status']) ?></div>
                            <?php if ($rx['prepared_at']): ?><span class="hint">Prepared by <?= h($rx['preparer'] ?: 'Clinic staff') ?> · <?= h($rx['prepared_at']) ?></span><?php endif; ?>
                            <?php if ($rx['dispensed_at']): ?><span class="hint">Dispensed by <?= h($rx['dispenser'] ?: 'Clinic staff') ?> · <?= h($rx['dispensed_at']) ?></span><?php endif; ?>
                            <div class="actions"><?php if ($rx['status'] !== 'Pending'): ?><a class="btn btn-light btn-small" href="?page=prescription&id=<?= $visitId ?>">Print prescription slip</a><?php endif; ?>
                            <?php if ($rx['status'] === 'Pending' && $workflow['can_prepare_prescription'] && in_array(($user['role'] ?? ''), ['Admin','Pharmacist'], true)): ?><?php formStart('prepare_prescription'); ?><input type="hidden" name="prescription_id" value="<?= (int)$rx['id'] ?>"><button class="btn btn-primary btn-small">Prepare & print slip</button></form>
                            <?php elseif ($rx['status'] === 'Pending'): ?><span class="hint">Pharmacy preparation unlocks after the doctor and laboratory steps are complete.</span>
                            <?php elseif (in_array($rx['status'], ['Prepared', 'Partially Dispensed'], true) && $workflow['can_dispense'] && in_array(($user['role'] ?? ''), ['Admin','Pharmacist'], true)): ?><?php formStart('dispense'); ?><input type="hidden" name="prescription_id" value="<?= (int)$rx['id'] ?>"><label class="receipt-check"><input type="checkbox" name="receipt_verified" value="1" required> I verified the patient's paid receipt</label><button class="btn btn-primary btn-small">Dispense & update stock</button></form>
                            <?php elseif (in_array($rx['status'], ['Prepared', 'Partially Dispensed'], true) && !$workflow['billing_done']): ?><span class="hint">Prepared: send the patient to the cashier for payment, then verify the receipt here.</span>
                            <?php elseif (in_array($rx['status'], ['Prepared', 'Partially Dispensed'], true)): ?><span class="hint">Payment is complete. The pharmacist must verify the receipt and dispense the medicine.</span>
                            <?php elseif ($rx['status'] !== 'Dispensed'): ?><span class="hint">Check the invoice and payment before continuing this prescription.</span><?php endif; ?></div>
                        </div><?php endforeach; ?></section><?php endif; ?>
                    <div class="grid-2">
                        <?php if ($workflow['billing_ready'] || $invoice || $workflow['completed']): ?><section class="card"><h2>Billing & payments</h2>
                            <?php if ($workflow['can_bill'] && (!$invoice || (float)$invoice['paid'] <= 0)): ?>
                                <?php if (in_array(($user['role'] ?? ''), ['Admin','Cashier'], true)): ?><?php formStart('invoice', 'invoice:' . $visitId); ?><input type="hidden" name="visit_id" value="<?= $visitId ?>"><div class="form-grid">
                                    <?php field('Consultation fee', 'consultation_fee', $invoice['consultation_fee'] ?? '0.00', 'number'); field('Lab / procedure / other charges', 'other_charges', $invoice['other_charges'] ?? '0.00', 'number'); field('Billing notes', 'notes', $invoice['notes'] ?? ''); ?>
                                </div><div class="actions"><button class="btn btn-primary">Save invoice</button></div></form>
                                <?php else: ?><div class="notice info">Prescription prepared. The cashier must create and settle the invoice before medicine is dispensed.</div><?php endif; ?>
                            <?php elseif (!$workflow['billing_ready'] && !$workflow['completed']): ?>
                                <div class="notice info">The cashier invoice unlocks after the doctor and laboratory review are complete and pharmacy has prepared every prescription.</div>
                            <?php elseif ($invoice && (float)$invoice['paid'] > 0): ?>
                                <div class="notice info">This invoice is locked because a payment has already been recorded.</div>
                            <?php endif; ?>
                            <?php if ($invoice): ?><hr class="line"><div class="detail-list"><div><span>Consultation</span><strong><?= money($invoice['consultation_fee']) ?></strong></div><div><span>Other charges</span><strong><?= money($invoice['other_charges']) ?></strong></div><div><span>Medicines</span><strong><?= money($invoice['medicine_total']) ?></strong></div><div><span>Total · paid · balance</span><strong><?= money($invoiceTotal) ?> · <?= money($invoice['paid']) ?> · <?= money(max(0, $invoiceTotal-(float)$invoice['paid'])) ?></strong></div></div>
                            <?php if ($workflow['can_bill'] && $invoiceTotal - (float)$invoice['paid'] > 0.00001): ?><hr class="line"><h3 style="font-size:13px">Record a payment</h3>
                                <?php if (in_array(($user['role'] ?? ''), ['Admin','Cashier'], true)): ?><?php formStart('payment', 'payment:' . (int)$invoice['id']); ?><input type="hidden" name="invoice_id" value="<?= (int)$invoice['id'] ?>"><div class="form-grid"><?php field('Amount', 'amount', number_format($invoiceTotal-(float)$invoice['paid'], 2, '.', ''), 'number', true); selectField('Payment method', 'payment_method', ['Cash'=>'Cash','Card'=>'Card','Insurance'=>'Insurance','Airtel Money'=>'Airtel Money','Other'=>'Other'], '', true); field('Payment reference', 'reference'); ?></div><div class="actions"><button class="btn btn-primary">Record payment & print receipt</button></div></form><?php else: ?><div class="notice info">The cashier records payment and prints the receipt. Bring the receipt back to pharmacy for dispensing.</div><?php endif; ?><?php endif; ?>
                            <a class="btn btn-light btn-small" href="?page=receipt&id=<?= $visitId ?>" target="_blank" style="margin-top:10px">Print receipt</a>
                            <?php if ($invoice['paid'] > 0): ?><div class="table-wrap" style="margin-top:10px"><table><thead><tr><th>Payment</th><th>Method</th><th>Reference</th><th>Date</th></tr></thead><tbody><?php $stmt=$pdo->prepare('SELECT * FROM payments WHERE invoice_id=? ORDER BY id DESC');$stmt->execute([$invoice['id']]);foreach($stmt->fetchAll() as $pay): ?><tr><td><?= money($pay['amount']) ?></td><td><?= h($pay['payment_method']) ?></td><td><?= h($pay['reference'] ?: '—') ?></td><td><?= h($pay['paid_at']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
                            <?php else: ?><p class="hint">Save an invoice to calculate the total and record payments. Medication charges use the current catalog price.</p><?php endif; ?>
                        </section><?php endif; ?>
                        <?php if (($workflow['billing_done'] && $workflow['pharmacy_done']) || $workflow['follow_up_scheduled'] || $workflow['completed']): ?><section class="card"><h2>Follow-up & case closure</h2><?php if ($followups): ?><div class="table-wrap"><table><thead><tr><th>Date</th><th>Specialist</th><th>Notes</th></tr></thead><tbody><?php foreach ($followups as $follow): ?><tr><td><?= h($follow['scheduled_date']) ?></td><td><?= h($follow['specialist'] ?: 'Clinic') ?></td><td><?= h($follow['notes'] ?: '—') ?></td></tr><?php endforeach; ?></tbody></table></div><hr class="line"><?php endif; ?>
                            <?php if ($workflow['can_follow_up'] && !$workflow['follow_up_scheduled']): ?><?php formStart('followup', 'followup:' . $visitId); ?><input type="hidden" name="visit_id" value="<?= $visitId ?>"><div class="form-grid"><?php field('Follow-up date', 'scheduled_date', '', 'date', true); field('Specialist / referral', 'specialist'); textareaField('Follow-up notes', 'notes', '', true); ?></div><div class="actions"><button class="btn btn-light">Schedule follow-up</button></div></form><p class="hint">Follow-up is optional. You can discharge the patient without scheduling another visit.</p><?php elseif (!$workflow['can_follow_up'] && !$workflow['completed']): ?><div class="notice info">Follow-up scheduling unlocks after the invoice is fully paid.</div><?php endif; ?>
                            <?php if ($workflow['billing_done'] && $workflow['pharmacy_done'] && !$workflow['completed']): ?><hr class="line"><?php formStart('close_visit'); ?><input type="hidden" name="visit_id" value="<?= $visitId ?>"><button class="btn btn-danger">Complete / discharge patient</button><span class="hint">The pharmacist has dispensed all paid medicines. Reception can check in any return visit using this patient record.</span></form><?php elseif ($workflow['completed']): ?><div class="notice success" style="margin-top:15px;margin-bottom:0">Visit completed<?= $visit['closed_at'] ? ' · ' . h($visit['closed_at']) : '' ?>. Reception can check this patient in again for a future visit.</div><?php endif; ?>
                        </section><?php endif; ?>
                    </div>
                    <?php
                }
}
?>